//! # Deterministic Event Ordering
//!
//! A total order for simulation inputs that are produced concurrently.
//!
//! When inputs are generated by several workers, the order they arrive in is a
//! property of thread scheduling, not of the simulation: two runs with the same
//! seed can produce the same *set* of payments and still execute them in a
//! different order, which changes routing, fee totals and every downstream
//! statistic. That makes a failure impossible to reproduce from the seed alone.
//!
//! [`order_events`] sorts events into a canonical order that depends only on the
//! events themselves, so `run(a) == run(permute(a))` for any permutation of the
//! same inputs.
//!
//! ## The order
//!
//! Events sort by, in priority order:
//!
//! 1. `timestamp` — when the event happened on the simulation's logical clock.
//! 2. `source` — node ID, lexicographic.
//! 3. `destination` — node ID, lexicographic.
//! 4. `amount` — numeric.
//! 5. `sequence` — the producer's submission counter, the last tie-break.
//!
//! Ties on everything but `sequence` are common: a batch of payments all stamped
//! with the same logical time. Ordering those by their payload rather than by
//! arrival means completion order of the producing threads cannot influence the
//! run. `sequence` is last because it is the only field that reflects *when*
//! something was submitted; using it earlier would reintroduce the dependency
//! on scheduling that this module exists to remove.

use crate::SimulatorError;
use serde::{Deserialize, Serialize};

/// One payment input to a simulation.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SimulationEvent {
    /// Logical time the event happened at.
    pub timestamp: u64,
    /// Submission counter within the run. Used only as the final tie-break.
    pub sequence: u64,
    /// Sending node ID.
    pub source: String,
    /// Receiving node ID.
    pub destination: String,
    /// Amount in stroops.
    pub amount: i128,
}

impl SimulationEvent {
    /// Create an event, rejecting inputs no simulation can execute.
    ///
    /// # Errors
    ///
    /// Returns [`SimulatorError::InvalidEvent`] for an empty node ID, a payment
    /// to itself, or a non-positive amount.
    pub fn new(
        timestamp: u64,
        sequence: u64,
        source: impl Into<String>,
        destination: impl Into<String>,
        amount: i128,
    ) -> Result<Self, SimulatorError> {
        let event = SimulationEvent {
            timestamp,
            sequence,
            source: source.into(),
            destination: destination.into(),
            amount,
        };
        event.validate()?;
        Ok(event)
    }

    /// Check the event in isolation: a payment needs two distinct endpoints and
    /// a positive amount.
    ///
    /// This cannot check that the nodes exist; that needs the network.
    pub fn validate(&self) -> Result<(), SimulatorError> {
        if self.source.is_empty() {
            return Err(SimulatorError::InvalidEvent(format!(
                "event {} has an empty source",
                self.sequence
            )));
        }
        if self.destination.is_empty() {
            return Err(SimulatorError::InvalidEvent(format!(
                "event {} has an empty destination",
                self.sequence
            )));
        }
        if self.source == self.destination {
            return Err(SimulatorError::InvalidEvent(format!(
                "event {} pays {} to itself",
                self.sequence, self.source
            )));
        }
        if self.amount <= 0 {
            return Err(SimulatorError::InvalidEvent(format!(
                "event {} has a non-positive amount ({})",
                self.sequence, self.amount
            )));
        }
        Ok(())
    }

    /// The key that defines the canonical order.
    pub fn order_key(&self) -> (u64, &str, &str, i128, u64) {
        (
            self.timestamp,
            self.source.as_str(),
            self.destination.as_str(),
            self.amount,
            self.sequence,
        )
    }
}

/// Sort events into their canonical order.
///
/// The result depends only on the events, not on the order they were passed in,
/// so the same multiset of inputs always produces the same simulation.
pub fn order_events<I>(events: I) -> Vec<SimulationEvent>
where
    I: IntoIterator<Item = SimulationEvent>,
{
    let mut events: Vec<SimulationEvent> = events.into_iter().collect();
    events.sort_by(|left, right| left.order_key().cmp(&right.order_key()));
    events
}

#[cfg(test)]
mod tests {
    use super::*;

    fn event(
        timestamp: u64,
        sequence: u64,
        source: &str,
        destination: &str,
        amount: i128,
    ) -> SimulationEvent {
        SimulationEvent::new(timestamp, sequence, source, destination, amount).unwrap()
    }

    #[test]
    fn ordering_is_independent_of_input_order() {
        let canonical = vec![
            event(0, 3, "a", "b", 100),
            event(0, 1, "a", "c", 200),
            event(0, 2, "b", "a", 300),
            event(1, 0, "c", "a", 50),
        ];

        let mut reversed = canonical.clone();
        reversed.reverse();

        let mut rotated = canonical.clone();
        rotated.rotate_left(2);

        let mut swapped = canonical.clone();
        swapped.swap(0, 2);

        for permutation in [reversed, rotated, swapped] {
            assert_eq!(order_events(permutation), canonical);
        }
    }

    #[test]
    fn timestamps_outrank_everything_else() {
        let events = vec![event(5, 0, "a", "b", 1), event(1, 9, "z", "y", 999)];
        let ordered = order_events(events);
        assert_eq!(ordered[0].timestamp, 1);
        assert_eq!(ordered[1].timestamp, 5);
    }

    #[test]
    fn payload_breaks_ties_before_sequence() {
        let events = vec![event(0, 0, "b", "a", 100), event(0, 5, "a", "b", 100)];
        let ordered = order_events(events);
        assert_eq!(ordered[0].source, "a");
        assert_eq!(ordered[1].source, "b");
    }

    #[test]
    fn sequence_breaks_a_full_payload_tie() {
        let events = vec![event(0, 7, "a", "b", 10), event(0, 2, "a", "b", 10)];
        let ordered = order_events(events);
        assert_eq!(ordered[0].sequence, 2);
        assert_eq!(ordered[1].sequence, 7);
    }

    #[test]
    fn amounts_order_numerically() {
        let events = vec![event(0, 0, "a", "b", 900), event(0, 0, "a", "b", 100)];
        let ordered = order_events(events);
        assert_eq!(ordered[0].amount, 100);
    }

    #[test]
    fn ordering_an_empty_or_single_batch_is_stable() {
        assert!(order_events(Vec::new()).is_empty());
        let single = vec![event(0, 0, "a", "b", 1)];
        assert_eq!(order_events(single.clone()), single);
    }

    #[test]
    fn invalid_events_are_rejected_with_the_offending_sequence() {
        assert!(SimulationEvent::new(0, 4, "", "b", 10).is_err());
        assert!(SimulationEvent::new(0, 4, "a", "", 10).is_err());
        assert!(SimulationEvent::new(0, 4, "a", "a", 10).is_err());

        let self_payment = SimulationEvent::new(0, 4, "a", "a", 10).unwrap_err();
        assert!(
            self_payment.to_string().contains("event 4"),
            "{self_payment}"
        );

        for amount in [0i128, -1] {
            let err = SimulationEvent::new(0, 9, "a", "b", amount).unwrap_err();
            assert!(matches!(err, SimulatorError::InvalidEvent(_)));
            assert!(err.to_string().contains("non-positive"), "{err}");
        }
    }
}
